-- Reminders and scheduled maintenance (pg_cron + pg_net -> send-reminders edge function).
--
-- Secrets stay inside the project:
--   * cron_secret is generated right here with gen_random_bytes and kept in Vault; send-reminders
--     checks callers against it with verify_cron_secret() (service role only).
--   * Web Push (VAPID) keys are generated by send-reminders on first use; the private key is kept
--     in Vault, the public key in app_public_config so the app can subscribe.
-- One-time setup per environment (not a secret):
--   select vault.create_secret('https://<project-ref>.supabase.co', 'project_url');
-- Until project_url exists the jobs log a warning and do nothing.

create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;

-- ---------------------------------------------------------------------------
-- Call an edge function from Postgres. Authenticated with a shared secret header,
-- because send-reminders uses the service role internally and must not be callable by users.
-- ---------------------------------------------------------------------------
create or replace function private.invoke_edge_function(p_name text, p_body jsonb default '{}')
returns bigint
language plpgsql
set search_path = ''
as $$
declare
  v_url text;
  v_secret text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'project_url' limit 1;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cron_secret' limit 1;
  if v_url is null or v_secret is null then
    raise warning 'FridgeWise: add the project_url and cron_secret Vault secrets to enable % (see README)', p_name;
    return null;
  end if;
  return net.http_post(
    url := rtrim(v_url, '/') || '/functions/v1/' || p_name,
    body := p_body,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secret),
    timeout_milliseconds := 60000
  );
end;
$$;

revoke all on function private.invoke_edge_function(text, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Secrets generated and kept inside the database
-- ---------------------------------------------------------------------------
create or replace function private.ensure_vault_secret(p_name text, p_value text, p_description text)
returns void
language plpgsql
set search_path = ''
as $$
begin
  if not exists (select 1 from vault.secrets where name = p_name) then
    perform vault.create_secret(p_value, p_name, p_description);
  end if;
end;
$$;

revoke all on function private.ensure_vault_secret(text, text, text) from public, anon, authenticated;

select private.ensure_vault_secret(
  'cron_secret',
  encode(extensions.gen_random_bytes(32), 'hex'),
  'Shared secret for pg_cron calls to the send-reminders edge function'
);

create or replace function public.verify_cron_secret(p_secret text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(p_secret, '') <> ''
     and exists (select 1 from vault.decrypted_secrets where name = 'cron_secret' and decrypted_secret = p_secret);
$$;

revoke all on function public.verify_cron_secret(text) from public, anon, authenticated;
grant execute on function public.verify_cron_secret(text) to service_role;

-- Public configuration the app may read (no secrets here). Holds the Web Push public key.
create table public.app_public_config (
  key text primary key check (key ~ '^[a-z_]{1,64}$'),
  value text not null,
  updated_at timestamptz not null default now()
);

alter table public.app_public_config enable row level security;
create policy "app_public_config: readable by signed-in users" on public.app_public_config
  for select to authenticated using (true);
revoke all on public.app_public_config from anon, authenticated;
grant select on public.app_public_config to authenticated;
grant all on public.app_public_config to service_role;

-- VAPID keys for Web Push. send-reminders creates them once; later calls return the stored pair.
create or replace function public.vapid_keys()
returns table (public_key text, private_key text)
language sql
stable
security definer
set search_path = ''
as $$
  select (select decrypted_secret from vault.decrypted_secrets where name = 'vapid_public_key' limit 1),
         (select decrypted_secret from vault.decrypted_secrets where name = 'vapid_private_key' limit 1);
$$;

create or replace function public.store_vapid_keys(p_public text, p_private text)
returns table (public_key text, private_key text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(hashtext('fridgewise-vapid-keys'));
  if not exists (select 1 from vault.secrets where name = 'vapid_private_key') then
    perform vault.create_secret(p_public, 'vapid_public_key', 'Web Push (VAPID) public key');
    perform vault.create_secret(p_private, 'vapid_private_key', 'Web Push (VAPID) private key');
  end if;
  insert into public.app_public_config (key, value)
  select 'vapid_public_key', k.public_key from public.vapid_keys() k
  on conflict (key) do update set value = excluded.value, updated_at = now();
  return query select * from public.vapid_keys();
end;
$$;

revoke all on function public.vapid_keys(), public.store_vapid_keys(text, text) from public, anon, authenticated;
grant execute on function public.vapid_keys(), public.store_vapid_keys(text, text) to service_role;

-- ---------------------------------------------------------------------------
-- due_reminders(): which users get a notification right now, and for which items.
--
-- * Items are active and expire between the user's local today and today + reminder_days_before.
-- * A user is notified once their local time is 8:00 or later (the job runs hourly, so every
--   timezone gets its reminder in the morning).
-- * Each item is reminded once when it enters the window and once more on the day it expires;
--   reminder_log (unique per item, day and channel) guarantees nothing is sent twice.
-- Only the service role may call this.
-- ---------------------------------------------------------------------------
create or replace function public.due_reminders()
returns table (
  user_id uuid,
  local_date date,
  items jsonb,
  subscriptions jsonb
)
language sql
stable
security invoker
set search_path = ''
as $$
  with prefs as (
    select p.id as user_id,
           p.reminder_days_before,
           (now() at time zone p.timezone)::date as local_date,
           extract(hour from now() at time zone p.timezone) as local_hour
    from public.profiles p
    where p.notify_push
  ),
  due as (
    select f.user_id, pr.local_date, f.id, f.name, f.expiration_date,
           (f.expiration_date - pr.local_date) as days_left
    from public.food_items f
    join prefs pr on pr.user_id = f.user_id
    where pr.local_hour >= 8
      and f.status = 'active'
      and f.expiration_date between pr.local_date and pr.local_date + pr.reminder_days_before
      and not exists (
        select 1 from public.reminder_log r
        where r.food_item_id = f.id
          and r.channel = 'push'
          and (r.sent_on = pr.local_date or f.expiration_date <> pr.local_date)
      )
  )
  select d.user_id,
         min(d.local_date) as local_date,
         jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name, 'expiration_date', d.expiration_date,
                                      'days_left', d.days_left)
                   order by d.expiration_date, d.name) as items,
         (select jsonb_agg(jsonb_build_object('id', s.id, 'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth))
            from public.push_subscriptions s where s.user_id = d.user_id) as subscriptions
  from due d
  where exists (select 1 from public.push_subscriptions s where s.user_id = d.user_id)
  group by d.user_id;
$$;

revoke all on function public.due_reminders() from public, anon, authenticated;
grant execute on function public.due_reminders() to service_role;

-- ---------------------------------------------------------------------------
-- Schedules (cron.schedule upserts by job name, so re-running this migration is safe).
-- ---------------------------------------------------------------------------
select cron.schedule(
  'fridgewise-send-reminders',
  '5 * * * *',
  $job$ select private.invoke_edge_function('send-reminders', '{"task": "reminders"}'::jsonb); $job$
);

select cron.schedule(
  'fridgewise-delete-old-scan-images',
  '17 3 * * *',
  $job$ select private.invoke_edge_function('send-reminders', '{"task": "cleanup"}'::jsonb); $job$
);
